# No header pulse. Time unit = 264us.
DENON_FREQUENCY_KHZ = 38
DENON_BIT_MARK_US = 264  # 1 unit
DENON_ONE_SPACE_US = 1848  # 7 units (264 * 7)
DENON_ZERO_SPACE_US = 792  # 3 units (264 * 3)
DENON_FRAME_GAP_US = 43560  # 165 units (264 * 165)

