# Airwit Plafondventilator (ceiling fan with light) — RF 433 MHz, OOK modulation.
# Codes captured from the original Broadlink learn flow; same wire format as IR
# but the type byte is 0xb2 (RF 433) instead of 0x26 (IR).
AIRWIT_FAN_FREQUENCY_HZ = 433_920_000

# The remote steps a 3-bit counter in the payload down by one on every press,
# cycling 7, 6, 5, 4, 3, 2, 1, 0 and around again, so no two presses in a row
# are identical on air and the receiver reads each one as a fresh press.
#
# When re-capturing these, do not use the Broadlink's frequency sweep. It needs
# the button held down and so consumes presses of its own, which makes the
# counter look as though it advances by two. find_rf_packet() takes a frequency
# directly, needs no sweep, and catches every press.
#
# Buttons whose effect depends on being seen as a fresh press need the whole
# cycle; rf_commands walks them in order. The fan speeds do not: "speed 3"
# means speed 3 however often it arrives, so they keep one fixed packet each.
AIRWIT_FAN_COUNTER_CYCLES: dict[str, tuple[str, ...]] = {
    # Six straight recordings of the lamp button, counters 6 down to 1,
    # captured back to back. Counters 7 and 0 are rebuilt from the counter-5
    # recording: same carrier frequency, pulse shapes and frame count, only
    # the payload bits differ.
    "lamp": (
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
    ),
    # Built from the recorded brightness-up packet (counter 6, eight frames),
    # keeping its waveform and varying only counter and checksum.
    "brightness_up": (
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
    ),
    # Built from the same waveform with command 25, since the recording of
    # this button started mid-frame and held only two whole frames, too few
    # for a press. These carry the eight the remote sends.
    "brightness_down": (
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
    ),
}

